/**
 * RoomCrypto - End-to-end encryption for collaboration rooms.
 *
 * Every room has a random 128-bit room secret generated by the host. The
 * secret travels only in the invite link's fragment (`#...&k=...`), which
 * browsers never send to the signaling relay or any HTTP server. The optional
 * PIN is mixed into the key as a second factor, so a leaked link alone is not
 * enough to read or write room traffic when a PIN is set.
 *
 * All peer-to-peer message payloads (`sync.*`, `user.*`) are sealed with
 * AES-GCM under a key derived with HKDF-SHA256 from (secret, room code, PIN).
 * The message id, type, room id and sender id are bound as additional
 * authenticated data so the relay cannot re-label a sealed payload as coming
 * from a different user or as a different message type.
 *
 * Because the secret has 128 bits of entropy, offline guessing of short PINs
 * is not possible without the link.
 */

import type { SyncMessage, SyncMessageType } from './types';
import { normalizePinCode } from './PinEncryption';

/** URL fragment parameter carrying the room secret. */
export const ROOM_SECRET_HASH_PARAM = 'k';
/** URL fragment parameter flagging that the room also needs a PIN. */
export const ROOM_PIN_REQUIRED_HASH_PARAM = 'pr';

const ROOM_SECRET_BYTES = 16;
const IV_LENGTH = 12;
const HKDF_SALT = 'openrv-web/room-key/v1';

/** Envelope that replaces a message payload once it is sealed. */
export interface EncryptedPayloadEnvelope {
  e2e: 1;
  iv: string;
  ct: string;
  /**
   * Routing hint kept in the clear so relays that route targeted messages keep
   * working. It is also covered by the ciphertext, which carries the real value.
   */
  targetUserId?: string;
}

function requireSubtle(): SubtleCrypto {
  const subtle = globalThis.crypto?.subtle;
  if (!subtle) {
    throw new Error('WebCrypto SubtleCrypto is not available in this environment.');
  }
  return subtle;
}

function toBase64Url(bytes: Uint8Array): string {
  let binary = '';
  const chunkSize = 0x8000;
  for (let offset = 0; offset < bytes.length; offset += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + chunkSize));
  }
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromBase64Url(value: string): Uint8Array {
  let b64 = value.replace(/-/g, '+').replace(/_/g, '/');
  const pad = b64.length % 4;
  if (pad === 2) b64 += '==';
  else if (pad === 3) b64 += '=';
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

/** Generate a fresh random room secret (base64url, 22 chars). */
export function generateRoomSecret(): string {
  return toBase64Url(crypto.getRandomValues(new Uint8Array(ROOM_SECRET_BYTES)));
}

/** A room secret is base64url text carrying at least 128 bits. */
export function isValidRoomSecret(value: unknown): value is string {
  return typeof value === 'string' && /^[A-Za-z0-9_-]{22,86}$/.test(value);
}

/**
 * Message types whose payloads are exchanged between peers and must be sealed.
 * Room lifecycle messages and keep-alives are addressed to the relay itself
 * and stay in the clear.
 */
export function isEncryptedMessageType(type: SyncMessageType): boolean {
  return type.startsWith('sync.') || type.startsWith('user.');
}

export function isEncryptedPayloadEnvelope(value: unknown): value is EncryptedPayloadEnvelope {
  if (!value || typeof value !== 'object') return false;
  const env = value as Record<string, unknown>;
  return env.e2e === 1 && typeof env.iv === 'string' && typeof env.ct === 'string';
}

/**
 * Derive the AES-GCM room key from the room secret, room code and optional PIN.
 */
export async function deriveRoomKey(secret: string, roomCode: string, pinCode = ''): Promise<CryptoKey> {
  if (!isValidRoomSecret(secret)) {
    throw new Error('Invalid room secret.');
  }
  const subtle = requireSubtle();
  const encoder = new TextEncoder();
  const ikm = await subtle.importKey('raw', fromBase64Url(secret) as unknown as BufferSource, 'HKDF', false, [
    'deriveKey',
  ]);
  return subtle.deriveKey(
    {
      name: 'HKDF',
      hash: 'SHA-256',
      salt: encoder.encode(HKDF_SALT) as unknown as BufferSource,
      info: encoder.encode(`${roomCode.trim().toUpperCase()}\n${normalizePinCode(pinCode)}`) as unknown as BufferSource,
    },
    ikm,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  );
}

function additionalData(message: Pick<SyncMessage, 'id' | 'type' | 'roomId' | 'userId'>): BufferSource {
  return new TextEncoder().encode(
    JSON.stringify([message.id, message.type, message.roomId, message.userId]),
  ) as unknown as BufferSource;
}

function readTargetUserId(payload: unknown): string | undefined {
  if (!payload || typeof payload !== 'object') return undefined;
  const target = (payload as { targetUserId?: unknown }).targetUserId;
  return typeof target === 'string' ? target : undefined;
}

/** Return a copy of `message` whose payload is sealed under `key`. */
export async function sealMessage(key: CryptoKey, message: SyncMessage): Promise<SyncMessage> {
  const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH));
  const plaintext = new TextEncoder().encode(JSON.stringify(message.payload ?? null));
  const ciphertext = await requireSubtle().encrypt(
    { name: 'AES-GCM', iv: iv as unknown as BufferSource, additionalData: additionalData(message) },
    key,
    plaintext as unknown as BufferSource,
  );
  const envelope: EncryptedPayloadEnvelope = {
    e2e: 1,
    iv: toBase64Url(iv),
    ct: toBase64Url(new Uint8Array(ciphertext)),
  };
  const targetUserId = readTargetUserId(message.payload);
  if (targetUserId) envelope.targetUserId = targetUserId;
  return { ...message, payload: envelope };
}

/**
 * Return a copy of `message` with its payload opened, or null when the payload
 * is not a valid envelope or fails authentication (wrong key, tampering).
 */
export async function openMessage(key: CryptoKey, message: SyncMessage): Promise<SyncMessage | null> {
  if (!isEncryptedPayloadEnvelope(message.payload)) return null;
  try {
    const plaintext = await requireSubtle().decrypt(
      {
        name: 'AES-GCM',
        iv: fromBase64Url(message.payload.iv) as unknown as BufferSource,
        additionalData: additionalData(message),
      },
      key,
      fromBase64Url(message.payload.ct) as unknown as BufferSource,
    );
    const payload: unknown = JSON.parse(new TextDecoder().decode(plaintext));
    if (payload === undefined) return null;
    return { ...message, payload };
  } catch {
    return null;
  }
}

// ---- Link helpers ----

function splitHash(hash: string): URLSearchParams {
  const cleaned = hash.startsWith('#') ? hash.slice(1) : hash;
  return new URLSearchParams(cleaned);
}

export interface RoomLinkSecret {
  secret: string | null;
  pinRequired: boolean;
}

/** Read the room secret and PIN flag from a URL fragment. */
export function readRoomLinkSecret(hash: string): RoomLinkSecret {
  const params = splitHash(hash);
  const secret = params.get(ROOM_SECRET_HASH_PARAM);
  return {
    secret: isValidRoomSecret(secret) ? secret : null,
    pinRequired: params.get(ROOM_PIN_REQUIRED_HASH_PARAM) === '1',
  };
}

/**
 * Return `url` with the room secret placed in its fragment, keeping any other
 * fragment parameters (such as the `s=` session state). Never touches the
 * query string, and strips any legacy `pin` query parameter.
 */
export function withRoomLinkSecret(url: string, secret: string, pinRequired: boolean): string {
  const fallbackBase = typeof window !== 'undefined' ? window.location.href : 'http://localhost/';
  const parsed = new URL(url, fallbackBase);
  parsed.searchParams.delete('pin');
  const cleaned = parsed.hash.startsWith('#') ? parsed.hash.slice(1) : parsed.hash;
  // Keep other fragment parts verbatim (the session state is base64url and must not be re-encoded).
  const parts = cleaned
    .split('&')
    .filter(
      (part) =>
        part.length > 0 &&
        !part.startsWith(`${ROOM_SECRET_HASH_PARAM}=`) &&
        !part.startsWith(`${ROOM_PIN_REQUIRED_HASH_PARAM}=`),
    );
  parts.push(`${ROOM_SECRET_HASH_PARAM}=${secret}`);
  if (pinRequired) parts.push(`${ROOM_PIN_REQUIRED_HASH_PARAM}=1`);
  parsed.hash = parts.join('&');
  return parsed.toString();
}

/**
 * Parse an invite link pasted where a room code is expected.
 * Returns null when the input is not a link carrying a room code.
 */
export function parseRoomInviteLink(
  input: string,
): { roomCode: string; secret: string | null; pinRequired: boolean } | null {
  const trimmed = input.trim();
  if (!/^https?:\/\//i.test(trimmed) && !trimmed.includes('room=')) return null;
  try {
    const fallbackBase = typeof window !== 'undefined' ? window.location.href : 'http://localhost/';
    const url = new URL(trimmed, fallbackBase);
    const roomCode = url.searchParams.get('room');
    if (!roomCode) return null;
    const { secret, pinRequired } = readRoomLinkSecret(url.hash);
    return { roomCode: roomCode.toUpperCase(), secret, pinRequired };
  } catch {
    return null;
  }
}
